fn render_feature_human(f: &forge::feature::FeatureDescriptor) -> String {
    [
        format!("id: {}", f.id),
        format!("version: {}", f.version),
        format!("profiles: {}", f.compatible_profiles.join(", ")),
        format!(
            "depends: {}",
            if f.depends.is_empty() {
                "none".to_string()
            } else {
                f.depends.join(", ")
            }
        ),
        format!(
            "conflicts: {}",
            if f.conflicts.is_empty() {
                "none".to_string()
            } else {
                f.conflicts.join(", ")
            }
        ),
        format!("install: {}", f.install_strategy),
        format!("upgrade: {}", f.upgrade_strategy),
        format!(
            "validation: {}",
            if f.validation.is_empty() {
                "manifest re-parse and graph re-resolution".to_string()
            } else {
                f.validation.join(", ")
            }
        ),
        format!("docs: {}", f.documentation),
        format!("tests: {}", f.tests),
    ]
    .join("\n")
}

/// Render an empty set as an explicit `none` so a reader never has to guess
/// whether a blank means "absent" or "omitted".
fn join_or_none(values: &[String]) -> String {
    if values.is_empty() {
        "none".to_string()
    } else {
        values.join(", ")
    }
}

pub(super) fn render_profile_human(p: &forge::profile::ProfileDescriptor) -> String {
    let mut lines = vec![
        format!(
            "id: {}\nversion: {}\nsupport_status: {}\nadapter: {}\nlanguage: {}\n",
            p.id,
            p.version,
            match p.support_status {
                forge::profile::ProfileSupportStatus::Supported => "supported",
                forge::profile::ProfileSupportStatus::Planned => "planned",
            },
            p.adapter,
            p.language,
        ),
        format!(
            "toolchain: {}{}",
            p.toolchain,
            p.toolchain_version
                .as_deref()
                .map(|v| format!("@{v}"))
                .unwrap_or_default()
        ),
        format!("capabilities: {}", p.capabilities.join(", ")),
        format!("packages: {}", p.packages.join(", ")),
        format!("layout: {}", p.layout.join(", ")),
        format!("conventions: {}", p.conventions.join(", ")),
        format!("build: {}", p.build_command),
        format!("test: {}", p.test_command),
        format!(
            "deployment: {}",
            match (&p.deployment_type, &p.deployment_target) {
                (Some(t), Some(target)) => format!("{t} -> {target}"),
                (Some(t), None) => t.clone(),
                (None, Some(target)) => target.clone(),
                (None, None) => "unknown".to_string(),
            }
        ),
        format!("quality: {}", p.quality_policies.join(", ")),
        format!(
            "requires_database: {}",
            if p.requires_database { "yes" } else { "no" }
        ),
    ];
    if let Some(desc) = &p.description {
        lines.push(format!("description: {desc}"));
    }
    // Shared-layer kit: the declared reference, its floor and — for a declared
    // zero — the reason the absence is recorded rather than implicit. Resolved
    // against the compiled-in registry so an unresolvable declaration is
    // visible here too, not only at generation time.
    match &p.kit {
        None => {
            lines.push("kit: none (profile predates the shared-layer kit contract)".to_string())
        }
        Some(reference) => {
            lines.push(format!(
                "kit: {}{}",
                reference.id,
                reference
                    .version
                    .as_deref()
                    .map(|v| format!("@{v}"))
                    .unwrap_or_else(|| " (declared zero, no version)".to_string())
            ));
            lines.push(format!("kit ecosystem: {}", reference.ecosystem.as_str()));
            if let Some(tfm) = &reference.tfm {
                lines.push(format!("kit tfm: {tfm}"));
            }
            if let Some(feed) = &reference.feed {
                lines.push(format!(
                    "kit feed: {} ({}) at {}",
                    feed.name,
                    feed.kind.as_str(),
                    feed.path
                ));
            }
            lines.push(format!(
                "kit minimum_packages: {}{}",
                reference.minimum_packages,
                if reference.is_declared_zero() {
                    " (declared zero, not a met floor)"
                } else {
                    ""
                }
            ));
            match forge::kit::inspect_kit(&reference.id, reference.version.as_deref()) {
                Ok(descriptor) => {
                    lines.push(format!(
                        "kit confirmed: {}",
                        join_or_none(&descriptor.confirmed_names())
                    ));
                    lines.push(format!(
                        "kit provisional: {}",
                        join_or_none(&descriptor.provisional_names())
                    ));
                    if !descriptor.assets.is_empty() {
                        lines.push(format!(
                            "kit assets: {}",
                            descriptor
                                .assets
                                .iter()
                                .map(|a| a.target.as_str())
                                .collect::<Vec<_>>()
                                .join(", ")
                        ));
                    }
                }
                // A declared zero is a *recorded* state, not a missing
                // registry row: its id is the `none` sentinel by design, so
                // saying it is unregistered would be actively misleading.
                Err(_) if reference.is_declared_zero() => {
                    lines.push("kit confirmed: none (declared zero)".to_string());
                    lines.push("kit provisional: none (declared zero)".to_string());
                }
                Err(_) => lines.push(
                    "kit: declared reference is not in the compiled-in kit registry".to_string(),
                ),
            }
            if let Some(reason) = &reference.zero_reason {
                lines.push(format!("kit zero_reason: {reason}"));
            }
        }
    }
    lines.join("\n")
}

pub(super) fn render_record_human(p: &ProjectRecord) -> String {
    let mut lines = vec![
        format!("id: {}", p.id),
        format!("name: {}", p.name),
        format!("path: {}", p.path),
        format!("profile: {}", p.profile),
        format!("schema: {}", p.schema_version),
        format!("platform: {}", p.platform_version),
        format!("maturity: {}", p.maturity.as_deref().unwrap_or("unknown")),
        format!(
            "target_maturity: {}",
            p.target_maturity.as_deref().unwrap_or("unknown")
        ),
        format!("stack: {}", p.stack.as_deref().unwrap_or("unknown")),
        format!("runtime: {}", p.runtime.as_deref().unwrap_or("unknown")),
        format!(
            "deployment_target: {}",
            p.deployment_target.as_deref().unwrap_or("unknown")
        ),
        format!(
            "git_remote: {}",
            p.git_remote.as_deref().unwrap_or("unknown")
        ),
        format!(
            "last_commit: {}",
            p.last_commit.as_deref().unwrap_or("unknown")
        ),
        format!(
            "quality: {}",
            p.quality_status.as_deref().unwrap_or("unknown")
        ),
        format!("agent: {}", p.agent_status.as_deref().unwrap_or("unknown")),
        format!("docs: {}", p.docs_status.as_deref().unwrap_or("unknown")),
        format!("observed_at: {}", p.observed_at),
        format!(
            "availability: {}",
            if p.available {
                "available"
            } else {
                "unavailable"
            }
        ),
    ];
    if p.mirror_remotes.is_empty() {
        lines.push("mirrors: none".to_string());
    } else {
        lines.push(format!("mirrors: {}", p.mirror_remotes.join(", ")));
    }
    if p.features.is_empty() {
        lines.push("features: none".to_string());
    } else {
        let feats: Vec<String> = p.features.iter().map(|(k, v)| format!("{k}={v}")).collect();
        lines.push(format!("features: {}", feats.join(", ")));
    }
    lines.join("\n")
}

pub(crate) fn render_error(err: &ForgeError, format: Format) {
    match format {
        Format::Human | Format::Table => eprintln!("error[{}]: {}", err.code(), err),
        Format::Json | Format::Ndjson => {
            let value = serde_json::json!({
                "error": {"code": err.code(), "message": err.to_string()}
            });
            eprintln!("{}", serde_json::to_string(&value).unwrap());
        }
    }
}

pub(super) fn truncate(s: &str, width: usize) -> String {
    if s.len() <= width {
        s.to_string()
    } else {
        format!("{}…", &s[..width.saturating_sub(1)])
    }
}
